import type {FetchDefinition} from '@github-ui/copilot-chat/test-utils/mock-interactive'
import {mockResponses} from '@github-ui/copilot-chat/test-utils/mock-interactive'
import {extractGates, mockEventStreamReplay} from '@github-ui/copilot-chat/test-utils/mock-streaming'
import type {CopilotChatMessage} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {render} from '@github-ui/react-core/test-utils'
import {screen, within} from '@testing-library/react'

import {CopilotImmersive} from '../../routes/CopilotImmersive'
import {getEditStream, getGenerationStream} from './stream-mocks'

// The import mocks have to be in test file due to jest behaviors (e.g. hoisting)
jest.mock('@github-ui/react-core/use-app-payload')
jest.mock('@github-ui/ssr-utils', () => ({
  ...jest.requireActual('@github-ui/ssr-utils'),
  // Allows safe-storage module to use local storage
  ssrSafeWindow: window,
  // Provides the current page location to useRouteThreadId
  ssrSafeLocation: {origin: 'https://github.localhost', pathname: '/copilot/c/123'},
}))

test('File generation', async () => {
  /*
    This tests asking copilot to generate us a simple webpage. It was generated by test/e2e/spec/copilot/recorder.spec.ts using
      const messages = [
        'generate a simple calculator using html, css, and javascript',
        'change the page title to "Calculator!"',
      ]
    This test uses the response to the first message.
    The 'file editing' test, below, uses the response to the second message.
  */

  const stream = getGenerationStream()
  const gates = extractGates(stream)

  mockResponses([
    ...startupResponses(),
    {
      request: {
        url: '/github/chat/threads/123/messages?',
        method: 'POST',
        body: {
          content: 'generate a simple calculator using html, css, and javascript',
          intent: 'conversation',
          streaming: true,
          mode: 'immersive',
        },
      },
      response: mockEventStreamReplay(stream),
    },
  ])

  const {user} = render(<CopilotImmersive />)
  const textArea = await screen.findByTestId('copilot-chat-input-textarea')
  await user.type(textArea, 'generate a simple calculator using html, css, and javascript')
  await user.keyboard('{enter}')

  // index.html streaming started
  await gates[0]?.entry.promise
  const response1 = await screen.findByTestId('message-streaming')
  expect(response1).toBeVisible()
  expect(await screen.findByText('calculator')).toBeVisible()
  // smooth streaming breaks up the message into <span> elements so we need to check the textContent
  expect(response1.textContent).toMatch(/Here is a simple calculator using HTML, CSS, and JavaScript/)

  // file block should be visible
  expect(await screen.findByLabelText('View file: index.html')).toBeVisible()
  // browser should be open
  const browser = await screen.findByTestId('content-preview')
  expect(browser).toBeVisible()
  // file content should be visible
  expect(await within(browser).findByText('<!DOCTYPE html>')).toBeVisible()
  // tab should be visible and selected
  let tab = await findTab(browser, 'index.html')
  expect(tab).toBeVisible()
  expect(tab).toHaveAttribute('aria-selected', 'true')
  // version selector should not be visible
  expect(screen.queryByTestId('version-selector')).toBeNull()
  // continue generation
  gates[0]?.exit.resolve()

  // styles.css streaming started
  await gates[1]?.entry.promise
  // styles.css tab should be visible and not selected
  tab = await findTab(browser, 'styles.css')
  expect(tab).toBeVisible()
  expect(tab).not.toHaveAttribute('aria-selected', 'true')
  // index.html tab should still be selected
  expect(await findTab(browser, 'index.html')).toHaveAttribute('aria-selected', 'true')
  // index.html content should still be visible
  expect(await within(browser).findByText('<!DOCTYPE html>')).toBeVisible()
  gates[1]?.exit.resolve()

  // end of the first message
  expect(await within(response1).findByLabelText('Message tools')).toBeVisible()
  expect(response1.textContent).toMatch(/in a web browser to see the calculator in action./)
})

test('file editing', async () => {
  /*
    This tests asking copilot to modify some files it previously created. It was generated by test/e2e/spec/copilot/recorder.spec.ts using
      const messages = [
        'generate a simple calculator using html, css, and javascript',
        'change the page title to "Calculator!"',
      ]
    This test loads the first two messages of that conversation in mockResponses(), and then streams the response to the third message.
  */
  const stream = getEditStream()
  const gates = extractGates(stream)

  mockResponses([
    ...startupResponses([
      {
        id: '91ad9bbe-94fb-46fc-815e-e55e6adda57b',
        parentMessageID: 'root',
        intent: 'conversation',
        role: 'user',
        content: 'generate a simple calculator using html, css, and javascript',
        createdAt: '2025-03-25T10:03:25.627659616-07:00',
        threadID: '3f1cacb4-31b1-46e7-ba53-44e8cb553bb4',
        references: [],
        skillExecutions: [],
        copilotAnnotations: {
          CodeVulnerability: null,
          PublicCodeReference: null,
        },
        interrupted: false,
        confirmations: null,
        clientConfirmations: [],
      },
      {
        id: '2ccc9b29-9843-4148-991f-fe27b0c6ad3a',
        parentMessageID: '91ad9bbe-94fb-46fc-815e-e55e6adda57b',
        intent: 'conversation',
        role: 'assistant',
        content:
          'Here is a simple calculator using HTML, CSS, and JavaScript:\n\n````html name=index.html\n<!DOCTYPE html>\n<html lang="en">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>Simple Calculator</title>\n    <link rel="stylesheet" href="styles.css">\n</head>\n<body>\n    <div class="calculator">\n        <input type="text" class="calculator-screen" value="" disabled />\n        <div class="calculator-keys">\n            <button type="button" class="operator" value="+">+</button>\n            <button type="button" class="operator" value="-">-</button>\n            <button type="button" class="operator" value="*">&times;</button>\n            <button type="button" class="operator" value="/">&divide;</button>\n\n            <button type="button" value="7">7</button>\n            <button type="button" value="8">8</button>\n            <button type="button" value="9">9</button>\n\n            <button type="button" value="4">4</button>\n            <button type="button" value="5">5</button>\n            <button type="button" value="6">6</button>\n\n            <button type="button" value="1">1</button>\n            <button type="button" value="2">2</button>\n            <button type="button" value="3">3</button>\n\n            <button type="button" value="0">0</button>\n            <button type="button" class="decimal" value=".">.</button>\n            <button type="button" class="all-clear" value="all-clear">AC</button>\n\n            <button type="button" class="equal-sign" value="=">=</button>\n        </div>\n    </div>\n    <script src="script.js"></script>\n</body>\n</html>\n````\n\n````css name=styles.css\nbody {\n    font-family: \'Arial\', sans-serif;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    height: 100vh;\n    background-color: #f4f4f4;\n}\n\n.calculator {\n    border-radius: 5px;\n    box-shadow: 0px 0px 20px 0px rgba(0, 0, 0, 0.2);\n    padding: 20px;\n    background-color: #fff;\n}\n\n.calculator-screen {\n    width: 100%;\n    height: 80px;\n    border: none;\n    background-color: #252525;\n    color: #fff;\n    text-align: right;\n    padding-right: 20px;\n    padding-left: 10px;\n    font-size: 2.5em;\n}\n\nbutton {\n    height: 60px;\n    font-size: 2em;\n    width: 25%;\n    background-color: #e0e0e0;\n    border: none;\n    float: left;\n    outline: none;\n}\n\nbutton:hover {\n    background-color: #d4d4d4;\n}\n\n.operator {\n    background-color: #ff9500;\n    color: #fff;\n}\n\n.operator:hover {\n    background-color: #e08d00;\n}\n\n.equal-sign {\n    background-color: #ff9500;\n    color: #fff;\n    height: calc(100% - 130px);\n    float: right;\n}\n\n.equal-sign:hover {\n    background-color: #e08d00;\n}\n\n.all-clear {\n    background-color: #ff3b30;\n    color: #fff;\n}\n\n.all-clear:hover {\n    background-color: #e02b20;\n}\n````\n\n````javascript name=script.js\nconst calculator = {\n    displayValue: \'0\',\n    firstOperand: null,\n    waitingForSecondOperand: false,\n    operator: null,\n};\n\nfunction inputDigit(digit) {\n    const { displayValue, waitingForSecondOperand } = calculator;\n\n    if (waitingForSecondOperand === true) {\n        calculator.displayValue = digit;\n        calculator.waitingForSecondOperand = false;\n    } else {\n        calculator.displayValue = displayValue === \'0\' ? digit : displayValue + digit;\n    }\n}\n\nfunction inputDecimal(dot) {\n    if (calculator.waitingForSecondOperand === true) return;\n\n    if (!calculator.displayValue.includes(dot)) {\n        calculator.displayValue += dot;\n    }\n}\n\nfunction handleOperator(nextOperator) {\n    const { firstOperand, displayValue, operator } = calculator;\n    const inputValue = parseFloat(displayValue);\n\n    if (operator && calculator.waitingForSecondOperand) {\n        calculator.operator = nextOperator;\n        return;\n    }\n\n    if (firstOperand == null && !isNaN(inputValue)) {\n        calculator.firstOperand = inputValue;\n    } else if (operator) {\n        const result = performCalculation[operator](firstOperand, inputValue);\n\n        calculator.displayValue = String(result);\n        calculator.firstOperand = result;\n    }\n\n    calculator.waitingForSecondOperand = true;\n    calculator.operator = nextOperator;\n}\n\nconst performCalculation = {\n    \'/\': (firstOperand, secondOperand) => firstOperand / secondOperand,\n\n    \'*\': (firstOperand, secondOperand) => firstOperand * secondOperand,\n\n    \'+\': (firstOperand, secondOperand) => firstOperand + secondOperand,\n\n    \'-\': (firstOperand, secondOperand) => firstOperand - secondOperand,\n\n    \'=\': (firstOperand, secondOperand) => secondOperand\n};\n\nfunction resetCalculator() {\n    calculator.displayValue = \'0\';\n    calculator.firstOperand = null;\n    calculator.waitingForSecondOperand = false;\n    calculator.operator = null;\n}\n\nfunction updateDisplay() {\n    const display = document.querySelector(\'.calculator-screen\');\n    display.value = calculator.displayValue;\n}\n\nupdateDisplay();\n\nconst keys = document.querySelector(\'.calculator-keys\');\nkeys.addEventListener(\'click\', (event) => {\n    const { target } = event;\n    if (!target.matches(\'button\')) {\n        return;\n    }\n\n    if (target.classList.contains(\'operator\')) {\n        handleOperator(target.value);\n        updateDisplay();\n        return;\n    }\n\n    if (target.classList.contains(\'decimal\')) {\n        inputDecimal(target.value);\n        updateDisplay();\n        return;\n    }\n\n    if (target.classList.contains(\'all-clear\')) {\n        resetCalculator();\n        updateDisplay();\n        return;\n    }\n\n    inputDigit(target.value);\n    updateDisplay();\n});\n````\n\nSave these files in the same directory and open `index.html` in a web browser to see the calculator in action.',
        createdAt: '2025-03-25T10:03:25.627661429-07:00',
        threadID: '3f1cacb4-31b1-46e7-ba53-44e8cb553bb4',
        references: [],
        skillExecutions: [],
        copilotAnnotations: {
          CodeVulnerability: [],
          PublicCodeReference: [],
        },
        interrupted: false,
        confirmations: null,
        clientConfirmations: null,
      },
    ]),
    {
      request: {
        url: '/github/chat/threads/123/messages?',
        method: 'POST',
        body: {
          content: 'change the page title to "Calculator!"',
          intent: 'conversation',
          streaming: true,
          mode: 'immersive',
        },
      },
      response: mockEventStreamReplay(stream),
    },
  ])

  const {user} = render(<CopilotImmersive />)

  // send message
  const textArea = await screen.findByTestId('copilot-chat-input-textarea')
  await user.type(textArea, 'change the page title to "Calculator!"')
  await user.keyboard('{enter}')

  await gates[0]?.entry.promise
  const response2 = await screen.findByTestId('message-streaming')
  expect(response2).toBeVisible()
  // file block should be visible
  expect(await within(response2).findByLabelText('View file: index.html')).toBeVisible()
  // version selector should be visible
  expect(screen.queryByTestId('version-selector')).toBeVisible()
  expect(screen.queryByTestId('version-selector')).toHaveTextContent('v2')
  gates[0]?.exit.resolve()

  expect(await within(response2).findByLabelText('Message tools')).toBeVisible()
  expect(response2.textContent).toMatch(
    /Here is the updated index.html file with the page title changed to "Calculator!":/,
  )
})

/**
 * finds the content preview tab for the given file.
 *
 * for some reason testing library's findByRole('tab', {name}) doesn't work for us
 */
async function findTab(browser: HTMLElement, name: string) {
  return (await within(browser).findByText(name)).closest('[role=tab]')
}

const startupResponses = (messages: CopilotChatMessage[] = []): FetchDefinition[] => [
  {
    request: {url: '/github/chat/threads?', method: 'GET'},
    response: {
      threads: [
        {
          id: '123',
          name: 'Thread Name',
          repoID: 0,
          repoOwnerID: 0,
          associatedRepoIDs: [],
          updatedAt: new Date().toString(),
        },
      ],
    },
  },
  {
    request: {url: '/github/chat/threads/123/messages', method: 'GET'},
    response: {
      thread: {id: '123'},
      messages,
    },
  },
]
